(function(){var e=document.querySelectorAll(`[data-views-slug]`);if(!e.length)return;fetch(`/api/views/all`).then(function(e){if(!e.ok)throw Error(`Failed to fetch`);return e.json()}).then(function(n){e.forEach(function(e){var r=n[e.getAttribute(`data-views-slug`)];e.textContent=typeof r==`number`?t(r):`0`})}).catch(function(){});function t(e){return e.toString().replace(/\B(?=(\d{3})+(?!\d))/g,`,`)}})();